style.css:
img[alt="Google"] {
  content: url("https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZGg2MDBpdnhscnYwaTV0dXczdHR0ZGZoNjZwa29rbGszbXE0c3FuZyZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/11j5OF7BTglVkc/giphy.gif") !important;
  width: 300px !important;   
  height: auto !important;
}
body {
  background: url("https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExeTcybTV3MmpqeWo2cTZlcHRvZnJ1ZThkeTN5djJjY3ExamVmdXVmdyZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/2g8EYDN0VWFMY/giphy.gif") no-repeat center center fixed !important;
  background-size: cover !important; 
}
input[type="submit"] {
  background: url("https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExZDYyZ2I1a3c3Ympmb2g5aDhqNDl6NmpwaXg0eWZ5MnU2OTZ2ZHJ5ayZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/VuehuL4fMHLgs/giphy.gif") no-repeat center !important;
  background-size: contain !important;
  color: transparent !important; 
  border: none !important;
  width: 60px !important;
  height: 60px !important;
}
img[alt="Google"] {
  animation: shake 1s infinite alternate;
}

@keyframes shake {
  from { transform: rotate(-3deg); }
  to { transform: rotate(3deg); }
}
